<?php require_once '../functions.php'; require_admin(); $title='Laporan Penjualan';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');if(isset($_GET['csv'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=laporan-penjualan.csv');$out=fopen('php://output','w');fputcsv($out,['ID Pesanan','Tanggal','Pelanggan','Total','Status']);$s=$koneksi->prepare("SELECT p.id_pesanan,p.created_at,u.nama,p.total,p.status FROM pesanan p JOIN users u ON u.id_user=p.id_user WHERE DATE(p.created_at) BETWEEN ? AND ? ORDER BY p.created_at DESC");$s->bind_param('ss',$from,$to);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())fputcsv($out,$x);fclose($out);exit;}$s=$koneksi->prepare("SELECT COUNT(*) jumlah,COALESCE(SUM(total),0) omzet FROM pesanan WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'cancelled'");$s->bind_param('ss',$from,$to);$s->execute();$summary=$s->get_result()->fetch_assoc();$s=$koneksi->prepare("SELECT DATE(created_at) tanggal,COUNT(*) transaksi,SUM(total) omzet FROM pesanan WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'cancelled' GROUP BY DATE(created_at) ORDER BY tanggal DESC");$s->bind_param('ss',$from,$to);$s->execute();$daily=$s->get_result();$s=$koneksi->prepare("SELECT d.id_produk,p.nama_produk,SUM(d.jumlah) qty,SUM(d.jumlah*d.harga) omzet FROM detail_pesanan d JOIN pesanan o ON o.id_pesanan=d.id_pesanan JOIN produk p ON p.id_produk=d.id_produk WHERE DATE(o.created_at) BETWEEN ? AND ? AND o.status<>'cancelled' GROUP BY d.id_produk,p.nama_produk ORDER BY qty DESC LIMIT 10");$s->bind_param('ss',$from,$to);$s->execute();$top=$s->get_result();include 'header.php'; ?>
<div class="container"><div class="section-head"><div><h1>Laporan Penjualan</h1><p class="muted">Rekap transaksi dan produk terlaris berdasarkan periode.</p></div><a class="btn" href="?from=<?=e($from)?>&to=<?=e($to)?>&csv=1">Export CSV</a></div><form class="filter-bar" method="get"><label>Dari<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Tampilkan</button></form><div class="stats"><div><small>Total Transaksi</small><b><?=$summary['jumlah']?></b></div><div><small>Total Omzet</small><b><?=rupiah($summary['omzet'])?></b></div></div><div class="two-col"><div class="panel"><h2>Penjualan Harian</h2><div class="table-wrap"><table><tr><th>Tanggal</th><th>Transaksi</th><th>Omzet</th></tr><?php while($d=$daily->fetch_assoc()):?><tr><td><?=$d['tanggal']?></td><td><?=$d['transaksi']?></td><td><?=rupiah($d['omzet'])?></td></tr><?php endwhile;?></table></div></div><div class="panel"><h2>Produk Terlaris</h2><div class="table-wrap"><table><tr><th>Produk</th><th>Qty</th><th>Omzet</th></tr><?php while($p=$top->fetch_assoc()):?><tr><td><?=e($p['nama_produk'])?></td><td><?=$p['qty']?></td><td><?=rupiah($p['omzet'])?></td></tr><?php endwhile;?></table></div></div></div></div><?php include '../footer.php'; ?>
